import type { DialogProps } from "./dialog.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { keyframes } from "@emotion/react";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import * as RadixDialog from "@radix-ui/react-dialog";
import { useMemo } from "react";

const componentName = "Dialog";

export const DialogClasses = {
  root: "exp-textura_dialog",
  body: "exp-textura_dialog_body",
  title: "exp-textura_dialog_title",
  content: "exp-textura_dialog_content",
  footer: "exp-textura_dialog_footer",
  overlay: "exp-textura_dialog_overlay",
  closeIconButton: "exp-textura_dialog_close_icon_button",
};

// Set up style variant settings for the component (if more than "default"), using style slots
// const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
//   exampleVariant: { root: { backgroundColor: theme.color.background.default } },
// });

const generateStyles = (props: Omit<DialogProps, "children">): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<DialogProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        // getVariantConfig(),
      ),
    [theme, variant, styleSlotsProp],
  );

  const fadeInOverlay = keyframes`from { opacity: 0; } to { opacity: ${styleSlots?.overlay?.opacity}; }`;
  const fadeOutOverlay = keyframes`from { opacity: ${styleSlots?.overlay?.opacity}; } to { opacity: 0; }`;

  const fadeInDialog = keyframes`from { opacity: 0; } to { opacity: 1; }`;
  const fadeOutDialog = keyframes`from { opacity: 1; } to { opacity: 0; }`;

  return {
    [`&.${DialogClasses.overlay}`]: {
      position: "fixed",
      inset: 0,
      animationTimingFunction: "ease",
      animationFillMode: "forwards",
      backgroundColor: theme.overlay.background,
      zIndex: theme.zIndex.dynamic,
      animationDuration: "100ms",
      '&[data-state="open"]': {
        animationName: fadeInOverlay,
        opacity: styleSlots?.overlay?.opacity,
      },
      '&[data-state="closed"]': {
        animationName: fadeOutOverlay,
        opacity: 0,
      },
      ...styleSlots?.overlay,
    },

    [`&.${DialogClasses.body}`]: {
      display: "flex",
      flexDirection: "column",
      position: "fixed",
      top: "50%",
      left: "50%",
      transform: "translate(-50%, -50%)",
      opacity: 1,
      animationTimingFunction: "ease",
      animationFillMode: "forwards",
      animationDuration: "100ms",
      backgroundColor: theme.dialog.color.background,
      color: theme.dialog.color.content,
      boxShadow: theme.dropShadow.lg,
      borderRadius: theme.toRem(theme.border.radius.sm),
      overflowY: "auto",
      maxWidth: "100vw",
      maxHeight: "calc(100% - 80px)",
      minWidth: theme.toRem(500),
      padding: theme.toRem(theme.spacing[24]),
      zIndex: theme.zIndex.dynamic,
      ...theme.typography.body.md,
      '&[data-state="open"]': {
        animationName: fadeInDialog,
        opacity: 1,
      },
      [`&[data-state="closed"]`]: {
        animationName: fadeOutDialog,
      },
      ...styleSlots?.body,
    },

    [`& .${DialogClasses.content}`]: {
      flex: "1 1 auto",
      overflowY: "auto",
      ...theme.typography.body.md,
      ...styleSlots?.content,
    },

    [`& .${DialogClasses.footer}`]: {
      paddingTop: theme.toRem(theme.spacing[24]),
      ...styleSlots?.footer,
    },

    [`& .${DialogClasses.title}`]: {
      ...theme.typography.heading.sm,
      margin: 0,
      color: theme.dialog.color.content,
      ...styleSlots?.title,
    },

    [`& .${DialogClasses.closeIconButton}`]: {
      position: "absolute",
      top: theme.toRem(theme.spacing[24]),
      right: theme.toRem(theme.spacing[16]),
      display: "inline-flex",
      alignItems: "center",
      justifyContent: "center",
      padding: theme.toRem(theme.spacing[8]),
      fontSize: theme.typography.fontSize[16],
      ":dir(rtl)": {
        right: "unset",
        left: theme.toRem(theme.spacing[16]),
      },
      "&:focus-visible": {
        ...styleSlots?.closeIconButtonFocus,
      },
      ...styleSlots?.closeIconButton,
    },

    ...styleSlots?.root,
  };
};

const excludedDOMProps = getExcludedDOMProps();

export const StyledDialog = styled(RadixDialog.Content, {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<Omit<DialogProps, "children">>((props) => generateStyles(props));

export const StyledDialogOverlay = styled(RadixDialog.Overlay, {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<Omit<DialogProps, "children">>((props) => generateStyles(props));
